// Op registry. Metadata comes from ops-index.js (generated by build.js) so search, the palette
// and the recipe can show every op before its category module has loaded.
import { categories, ops } from './ops-index.js';

export { categories, ops };
export const byId = new Map(ops.map((o) => [o.id, o]));
export const catById = new Map(categories.map((c) => [c.id, c]));

const loading = new Map();

export function loadCategory(catId) {
  if (!loading.has(catId)) {
    const cat = catById.get(catId);
    const p = import(cat.file).then((m) => new Map(m.default.map((op) => [op.id, op])));
    p.catch(() => loading.delete(catId));
    loading.set(catId, p);
  }
  return loading.get(catId);
}

export async function getOp(id) {
  const meta = byId.get(id);
  if (!meta) throw Object.assign(new Error(`Unknown op ${id}`), { name: 'OpError' });
  return (await loadCategory(meta.cat)).get(id);
}

export const loadAll = () => Promise.all(categories.map((c) => loadCategory(c.id)));
